const crypto = require('crypto');
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const json      = items[i].json;
  const secret    = $env.CHATWOOT_WEBHOOK_SECRET;
  const received  = json.headers['x-chatwoot-signature'];
  const timestamp = json.headers['x-chatwoot-timestamp'];

  let ok = false, expected = null, rawLen = null, rawPreview = null, err = null;
  try {
    const rawBuf = await this.helpers.getBinaryDataBuffer(i, 'data');   // 'data' = nombre de la prop binaria
    rawLen = rawBuf.length;
    rawPreview = rawBuf.toString('utf8').slice(0, 60);

    const signed = Buffer.concat([Buffer.from(`${timestamp}.`), rawBuf]);
    expected = 'sha256=' + crypto.createHmac('sha256', secret).update(signed).digest('hex');

    ok = !!received
      && expected.length === received.length
      && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(received));
  } catch (e) {
    err = String(e.message || e);
  }

  out.push({ json: { ...json, _hmac: { ok, expected, received, timestamp, rawLen, rawPreview, err } }, pairedItem: { item: i } });
}

return out;

// === DECIDIR — decide QUÉ hacer y arma la conversación (sin catálogo: eso lo inyecta 'Armar mensajes') ===
const webhookData = $('Chatwoot Webhook').first().json;
const body = webhookData.body;
const myMessageId = body.id;
const conversationId = body.conversation.id;
const accountId = body.account.id;

// F5: created_at robusto (unix int, string numérico o ISO) → siempre número
const num = (v) => {
  if (v == null) return 0;
  if (typeof v === 'number') return v;
  const n = Number(v);
  if (Number.isFinite(n)) return n;
  const t = Date.parse(v);
  return Number.isFinite(t) ? t : 0;
};
const myCreatedAt = num(body.created_at);

const historialJson = $('Get Historial').first().json;
const rawPayload = historialJson.payload;
const allMessages = Array.isArray(rawPayload) ? rawPayload : (rawPayload && rawPayload.messages ? rawPayload.messages : []);

const isIn = (m) => m.message_type === 'incoming' || m.message_type === 0;
const isOut = (m) => (m.message_type === 'outgoing' || m.message_type === 1) && !m.private;
const hasContent = (m) => m.content && String(m.content).trim().length > 0;

const sorted = allMessages.slice().sort((a, b) => num(a.created_at) - num(b.created_at));

// DEBOUNCE (F1): el "último" es el último ENTRANTE CON TEXTO.
// Una foto que llega después de la pregunta ya no gana el "soy el último".
const incoming = sorted.filter((m) => isIn(m) && hasContent(m));
const lastIncoming = incoming.length ? incoming[incoming.length - 1] : null;
if (lastIncoming && myMessageId && lastIncoming.id !== myMessageId) {
  return [{ json: { action: 'skip', reason: 'no-soy-el-ultimo', conversationId, accountId } }];
}

// IDEMPOTENCIA (F5): ya hay respuesta posterior a mi mensaje → no repito
const repliedAfter = sorted.some((m) => isOut(m) && num(m.created_at) > myCreatedAt);
if (repliedAfter) {
  return [{ json: { action: 'skip', reason: 'ya-respondido', conversationId, accountId } }];
}

// Ráfaga del cliente = entrantes con texto desde la última salida
let lastOutIdx = -1;
for (let i = sorted.length - 1; i >= 0; i--) {
  if (isOut(sorted[i])) { lastOutIdx = i; break; }
}
const burst = sorted.slice(lastOutIdx + 1).filter((m) => isIn(m) && hasContent(m)).map((m) => m.content);
const mergedUser = burst.join('\n');

if (!mergedUser) {
  return [{ json: { action: 'skip', reason: 'sin-texto-nuevo', conversationId, accountId } }];
}

// INJECTION: regex sobre el texto agregado (red barata; Tier-1 lo duplicará)
const INJECTION_PATTERNS = [
  /ignor[aá].*(instrucciones|reglas|rol)/i,
  /olvid[aá].*(instrucciones|reglas|rol)/i,
  /nuevo rol/i,
  /ignore (previous|instructions|your)/i,
  /system prompt/i,
  /jailbreak/i,
  /\bDAN\b/,
  /pretend you are/i,
  /do anything now/i,
  /forget your instructions/i
];
if (INJECTION_PATTERNS.some((p) => p.test(mergedUser))) {
  return [{ json: { action: 'injection', conversationId, accountId } }];
}

// PRIMER MENSAJE (F3): saludo enlatado SOLO si el texto es un saludo puro.
// Primer mensaje con pregunta → process (lo contesta el LLM).
const hasOutgoing = sorted.some(isOut);
function isGreetingOnly(text) {
  const t = (text || '')
    .toLowerCase()
    .replace(/[¡!¿?.,;:()"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!t) return false;
  const G = '(hola|holis|buenas|buen dia|buen día|buenos dias|buenos días|buenas tardes|buenas noches|hey|que tal|qué tal|como andas|cómo andás|como va|cómo va|todo bien)';
  const re = new RegExp('^' + G + '( ' + G + ')*$');
  return re.test(t);
}
if (!hasOutgoing && isGreetingOnly(mergedUser)) {
  return [{ json: { action: 'primer-mensaje', conversationId, accountId } }];
}

// CAP DE RESPUESTAS POR CONVERSACIÓN (ventana rodante 24h): tope duro para floods sostenidos.
const CAP_RESPUESTAS = 25;
const nowMs = Date.now();
const botOut = sorted.filter((m) => isOut(m) && hasContent(m));
const botOut24 = botOut.filter((m) => nowMs - num(m.created_at) < 86400000);
const CAP_MARK = 'muchos mensajes en esta conversación';
if (botOut24.length >= CAP_RESPUESTAS) {
  const capYaAvisado = botOut24.some((m) => String(m.content).toLowerCase().includes(CAP_MARK));
  if (capYaAvisado) {
    return [{ json: { action: 'skip', reason: 'cap-ya-avisado', conversationId, accountId } }];
  }
  return [{ json: { action: 'cap', conversationId, accountId } }];
}

// PROCESS: armar la conversación (sin system, sin catálogo). 'Armar mensajes' le prepende el system+catálogo.
// ¿ya se le avisó al cliente que el canal es solo informativo? (buscamos el email del negocio en salientes del bot)
const avisoDado = sorted.some((m) => isOut(m) && hasContent(m) && String(m.content).toLowerCase().includes('terminalgrafica@gmail.com'));
// Últimas 3 respuestas del bot → el LLM las usa para no repetirse (action noop)
const lastBotReplies = botOut.slice(-3).map((m) => String(m.content));

const conversation = [];
const history = sorted.slice(0, lastOutIdx + 1).slice(-6);
for (const m of history) {
  if (isIn(m) && hasContent(m)) {
    conversation.push({ role: 'user', content: m.content });
  } else if (isOut(m) && hasContent(m)) {
    conversation.push({ role: 'assistant', content: m.content });
  }
}
conversation.push({ role: 'user', content: mergedUser });

return [{ json: { action: 'process', conversation, userMessage: mergedUser, avisoDado, lastBotReplies, conversationId, accountId } }];

const input = $input.first().json;
const sd = $getWorkflowStaticData('global');
const TTL_MS = 10 * 60 * 1000; // 10 min — subilo si el catálogo casi no cambia

const fresh = sd.catalogo && sd.catalogoTs && (Date.now() - sd.catalogoTs) < TTL_MS;

return [{
  json: { ...input, _cacheHit: !!fresh, _catalogo: fresh ? sd.catalogo : null },
  pairedItem: { item: 0 },
}];

const input = $input.first().json;
const sd = $getWorkflowStaticData('global');
const fresh = input.catalogo; // la query devuelve { catalogo }

let cat;
if (fresh) {
  cat = fresh;
  sd.catalogo = cat;
  sd.catalogoTs = Date.now();
} else {
  // la query falló (onError=continueRegularOutput) → servimos cache viejo si hay
  cat = sd.catalogo || '(catalogo no disponible)';
}

return [{
  json: { _catalogo: cat, _cacheHit: false, _stale: !fresh },
  pairedItem: { item: 0 },
}];

const decidir = $('Decidir').first().json;
const conversation = decidir.conversation || [];
const catalogo = $input.first().json._catalogo || '(catalogo no disponible)';

// C2: ruta deterministica desde la telemetria (Get Ruta Cotizador). Si la ultima
// accion de ESTA conversacion fue una pregunta de cotizacion reciente, el turno lo
// atiende el prompt ESPECIALISTA con solo el catalogo cotizable. 'forzarGeneral'
// (action volver del especialista) pisa la ruta -> cota estructural de 1 vuelta.
const RUTA_TTL_SEG = 1800;
let rutaCotizador = false;
try {
  const r = $('Get Ruta Cotizador').first().json || {};
  rutaCotizador = ['pregunto_opciones', 'cotizador_answer'].includes(r.accion) && Number(r.edad_seg) < RUTA_TTL_SEG;
} catch (e) { rutaCotizador = false; }
if ($input.first().json.forzarGeneral === true) rutaCotizador = false;

let systemPrompt;
if (rutaCotizador) {
  // catalogo cotizable derivado del MISMO cache (coherencia con main garantizada):
  // headers RUBRO + lineas '- ' con alguna opcion con precio (*). Sin la leyenda
  // del main: el prompt cotizador trae su propio framing corto.
  const out = [];
  let header = null;
  for (const l of String(catalogo).split('\n')) {
    if (/^RUBRO:/i.test(l.trim())) { header = l; continue; }
    if (l.trim().startsWith('-') && l.includes('*')) {
      if (header) { if (out.length) out.push(''); out.push(header); header = null; }
      out.push(l);
    }
  }
  systemPrompt = $('Prompt Cotizador').first().json.promptCotizador.replace('__CATALOGO__', out.join('\n') || '(sin lineas cotizables)');
} else {
  systemPrompt = $('System Prompt').first().json.systemPrompt.replace('__CATALOGO__', catalogo);
}

const avisoNote = decidir.avisoDado
  ? 'ESTADO INTERNO (no lo menciones textualmente): al cliente YA se le avisó que este canal es solo informativo y que los pedidos se hacen por email. NO repitas ese aviso; seguí contestando normal sus consultas.'
  : 'ESTADO INTERNO (no lo menciones textualmente): al cliente TODAVÍA no se le avisó sobre el canal informativo/email.';

const lastBotReplies = decidir.lastBotReplies || [];
const repeatNote = lastBotReplies.length
  ? 'ESTADO INTERNO (no lo menciones): tus últimas respuestas en esta conversación fueron:  ' + lastBotReplies.map((r, i) => '[' + (i + 1) + '] ' + r).join('   ///   ') + '.  Si tu respuesta no agregaría nada nuevo (misma intención o información) respecto de estas, y el cliente no sumó una pregunta ni un dato nuevo, respondé con action noop. Excepción: si el cliente REPITE una pregunta o manda solo signos ("?", "???"), está esperando respuesta — contestale de nuevo, reformulado, NUNCA noop.'
  : 'ESTADO INTERNO: todavía no diste ninguna respuesta en esta conversación.';

// el especialista no maneja email/cierre -> avisoNote solo en ruta general
const llmMessages = rutaCotizador
  ? [{ role: 'system', content: systemPrompt }, { role: 'system', content: repeatNote }, ...conversation]
  : [{ role: 'system', content: systemPrompt }, { role: 'system', content: avisoNote }, { role: 'system', content: repeatNote }, ...conversation];

return [{ json: { ...decidir, llmMessages, rutaCotizador }, pairedItem: { item: 0 } }];

// Parsea la salida JSON del LLM de forma tolerante. Fallback seguro = handoff.
const decidir = $('Decidir').first().json;

let raw = '';
try { raw = $input.first().json.choices[0].message.content || ''; } catch (e) { raw = ''; }

let txt = String(raw).trim();
// sacar posibles fences ```json ... ```
if (txt.startsWith('```')) {
  txt = txt.replace(/^```[a-zA-Z]*\s*/, '').replace(/```\s*$/, '').trim();
}

let action = 'handoff', reply = '', motivo = '', producto = '', variante = '', mas = [], cantidad = null, paginas = null, copias = null, flags = [], opcionesObj = null;
try {
  const obj = JSON.parse(txt);
  action = String(obj.action || '').toLowerCase();
  reply = typeof obj.reply === 'string' ? obj.reply : '';
  motivo = typeof obj.motivo === 'string' ? obj.motivo : '';
  if (action === 'precio') {
    producto = typeof obj.producto === 'string' ? obj.producto.trim() : '';
    variante = (typeof obj.variante === 'string' ? obj.variante : '').replace(/\*+\s*$/, '').trim();
    if (Array.isArray(obj.mas)) {
      mas = obj.mas.slice(0, 2).map((m) => {
        const mc = typeof m?.cantidad === 'string' && /^\d{1,6}$/.test(m.cantidad.trim()) ? Number(m.cantidad.trim()) : m?.cantidad;
        return {
          producto: typeof m?.producto === 'string' ? m.producto.trim() : '',
          variante: (typeof m?.variante === 'string' ? m.variante : '').replace(/\*+\s*$/, '').trim(),
          cantidad: Number.isInteger(mc) && mc >= 1 && mc <= 999999 ? mc : null,
        };
      }).filter((m) => m.producto);
    }
    const entero = (val, max) => {
      const c = typeof val === 'string' && /^\d{1,6}$/.test(val.trim()) ? Number(val.trim()) : val;
      return Number.isInteger(c) && c >= 1 && c <= max ? c : null;
    };
    cantidad = entero(obj.cantidad, 999999);
    paginas = entero(obj.paginas, 5000);
    copias = entero(obj.copias, 1000);
    // copias sin paginas: no hay unidad base para multiplicar -> se ignoran ambos
    if (copias !== null && paginas === null) { copias = null; flags.push('copias_sin_paginas'); }
  }
  if (action === 'opciones') {
    const prods = Array.isArray(obj.productos) ? obj.productos.slice(0, 4).map((x) => typeof x === 'string' ? x.trim() : '').filter(Boolean) : [];
    const FALTAN_OK = ['cantidad', 'paginas', 'copias', 'producto', 'opcion'];
    opcionesObj = { productos: prods, faltan: Array.isArray(obj.faltan) ? obj.faltan.filter((x) => FALTAN_OK.includes(x)) : [] };
  }
  if (!['answer', 'handoff', 'noop', 'precio', 'opciones', 'volver'].includes(action)) action = 'handoff';
} catch (e) {
  action = 'handoff'; reply = ''; motivo = 'respuesta del modelo ilegible';
}
// C2: 'volver' solo vale viniendo del especialista; en ruta general se descarta a
// handoff (cota estructural del ciclo volver->general: 1 vuelta por ejecucion).
let rutaCot = false;
try { rutaCot = $('Armar Mensajes LLM').first().json.rutaCotizador === true; } catch (e) { rutaCot = false; }
if (action === 'volver' && !rutaCot) { action = 'handoff'; motivo = 'action volver fuera de ruta cotizador'; }
if (action === 'volver' || action === 'opciones') reply = '';
if (action === 'handoff' && !motivo.trim()) motivo = 'sin motivo especificado';

// answer sin texto = no hay nada que mandar → silencio (noop), NO handoff (no escalamos ruido a un humano)
if (action === 'answer' && !reply.trim()) {
  action = 'noop';
}

// BACKSTOP PRIMERA MENCION: si el mail ya se menciono y el cliente NO lo pide, no repetir la direccion.
const pideMail = /mail|correo|casilla|direcci/i.test(decidir.userMessage || '');
if (decidir.avisoDado && !pideMail && reply) {
  // Cascada de especifico a pelado (hallazgo R1 ronda 2: "a nuestro email nuestro mail").
  // Absorbe el lead-in que el LLM ya puso (a/al + nuestro/el/la + email/mail/correo/
  // casilla/direccion (de correo) + ':' opcional) para no dejar la frase duplicada.
  reply = reply
    .replace(/(?:por\s+(?:e-?mail|mail|correo)\s+)?\b(?:a|al)\s+(?:(?:nuestr[oa]|el|la)\s+)?(?:(?:e-?mail|mail|correo|casilla|direcci[oó]n(?:\s+de\s+(?:correo|e-?mail|mail))?)\s*:?\s*)?terminalgrafica@gmail\.com/gi, 'a nuestro mail')
    .replace(/\b(?:(?:nuestr[oa]|el|la)\s+)?(?:e-?mail|mail|correo|casilla|direcci[oó]n(?:\s+de\s+(?:correo|e-?mail|mail))?)\s*:?\s*terminalgrafica@gmail\.com/gi, 'nuestro mail')
    .replace(/terminalgrafica@gmail\.com/gi, 'nuestro mail');
}

// BACKSTOP DETERMINISTICO ANTI-REPETICION
// Red de seguridad para cuando el LLM NO se auto-silencia (action noop) y repite textual.
// Normaliza y compara la respuesta candidata contra las ultimas del bot (Decidir.lastBotReplies, ultimas 3).
// Umbral 2 a proposito (no 1): protege el repetir legitimo a pedido ("no me llego, repetimelo").
// Si el bot YA dijo esto ~igual 2+ veces recientes, un 3er envio es un loop -> noop.
const MAX_REPETICIONES = 2;
const normRep = (s) => String(s || '')
  .toLowerCase()
  .replace(/[*_`~#>\-]/g, ' ')
  .replace(/[¡!¿?.,;:()"']/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
if (action === 'answer' && reply.trim()) {
  const recientes = Array.isArray(decidir.lastBotReplies) ? decidir.lastBotReplies : [];
  const cand = normRep(reply);
  if (cand) {
    const repeticiones = recientes.filter((r) => normRep(r) === cand).length;
    if (repeticiones >= MAX_REPETICIONES) {
      action = 'noop';
    }
  }
}

// RAMA PRECIO — backstops deterministicos (el LLM NUNCA tipea el numero):
// - {{PRECIO}} debe aparecer exactamente una vez en el template;
// - si el LLM escribio un patron de plata igual, se descarta su texto (plantilla fija).
// producto/variante vacios NO degradan aca: Get Precio dara 0 filas -> fallback email.
let precio = null;
if (action === 'precio') {
  const template = reply;
  const marcas = (template.match(/\{\{PRECIO\}\}/g) || []).length;
  const plataRe = /(\$\s*\d)|(\d[\d.,]*\s*(pesos|ars)\b)/i;
  const forzarPlantilla = marcas !== 1 || plataRe.test(template.replace(/\{\{PRECIO\}\}/g, ''));
  precio = { producto, variante, template, forzarPlantilla, mas, cantidad, paginas, copias, flags };
  reply = '';
}

if (action === 'noop') reply = '';

return [{
  json: {
    action, reply, motivo, precio, opciones: opcionesObj,
    conversationId: decidir.conversationId,
    accountId: decidir.accountId,
    userMessage: decidir.userMessage,
  },
  pairedItem: { item: 0 },
}];

const decidir = $('Decidir').first().json;
const conversationMsgs = decidir.conversation || [];

// Presentar como transcript plano — evita que el LLM "continúe" el diálogo en lugar de resumirlo
const transcript = conversationMsgs.map(m => {
  const label = m.role === 'user' ? 'CLIENTE' : 'EQUIPO';
  return `[${label}]: ${m.content}`;
}).join('\n');

const noteMessages = [
  {
    role: 'system',
    content: 'Sos un asistente interno de Terminal Gráfica. NO respondas al cliente. Tu ÚNICA tarea es redactar una nota de traspaso para el asesor humano que va a tomar esta conversación.'
  },
  {
    role: 'user',
    content: `Conversación de WhatsApp:\n\n${transcript}\n\nRedactá la nota de traspaso. Incluí:\n- Qué quiere el cliente (una línea)\n- Datos mencionados (producto, cantidad, formato, etc.) — SOLO lo que el cliente dijo explícitamente, no inventes datos ni precios\n- Próximo paso sugerido para el asesor\n\nMáximo 5 líneas. Tono directo, para uso interno.`
  }
];

return [{
  json: {
    noteMessages,
    conversationId: decidir.conversationId,
    accountId: decidir.accountId
  }
}];

// Rama Fail del Guardrails Tier-2. Distingue una VIOLACIÓN REAL (jailbreak/topical
// flaggeado por el modelo) de una CAÍDA del modelo-guard (executionFailed) o un item
// de error del nodo. Fail-open ante caída: no penaliza, deja seguir al LLM principal
// (que ya degrada a handoff si OpenRouter está caído).
const j = $input.first().json;
const checks = Array.isArray(j.checks) ? j.checks : [];
const violated = checks.filter((c) => c && c.triggered && !c.executionFailed);
const realViolation = violated.length > 0;
// reason = nombre del guard que disparó (jailbreak | topicalAlignment)
const reason = realViolation ? String(violated[0].name || 'tier2') : 'model_error';

const b = $('Chatwoot Webhook').first().json.body;
const sid = b.sender?.id ?? b.conversation?.meta?.sender?.id ?? '';
const decidir = $('Decidir').first().json;

return [{
  json: {
    realViolation,
    reason,
    senderKey: String(sid),
    conversationId: decidir.conversationId,
    accountId: decidir.accountId,
    userMessage: decidir.userMessage,
  },
  pairedItem: { item: 0 },
}];

// v7 COTIZADOR — Rama precio: inyeccion deterministica desde bot.variantes (mismas filas que el
// motor del mostrador — nunca recalcular = no precio fantasma). El LLM nunca ve
// reglas ni tipea montos. Escalera deterministica POR ITEM (main + hasta 2
// extras via campo 'mas'), cada uno con su propio estado:
//   override / 2+ reglas de cantidad / precio $0  -> sin numero (email)
//   exactamente 1 regla de cantidad               -> tabla de rangos verbatim + caveat
//   sin reglas                                    -> numero limpio
//   resto (descuentos/adicionales)                -> numero de lista + caveat neutro
const parsear = $('Parsear Respuesta').first().json;
const decidir = $('Decidir').first().json;
const p = parsear.precio || {};
// Item de error de Get Precio (onError continueRegularOutput): distinguir fallo SQL
// de un no-match real en la telemetria (el cliente recibe el mismo fallback igual).
const errItem = $input.all().find((i) => i.json && i.json.error);

// v7 r4: ventana de los ultimos 3 mensajes ENTRANTES (incluido el actual) para los
// guards que un solo turno no cubre (suite-5 real: el bookcel quedo en el mensaje
// anterior y el follow-up recibio total).
const PAPEL_RE = /book\s*cell?|(?:papel(?:es)?|hojas?)\s+(?:de\s+)?(?:color(?:es)?|celestes?|amarill\w*|rosad\w*|rosas?|verdes?|azul(?:es)?|roj[ao]s?|naranjas?|violetas?|lilas?|cremas?|fucsias?|gris(?:es)?|negr[ao]s?)|m[aá]s\s+grueso|mejor\s+papel|papel\s+mejor/i;
const CORRECCION_RE = /(?:papel|hoja)s?\s+(?:com[uú]n|normal|blanc[oa]|de\s+siempre)|sin\s+(?:el\s+)?(?:bookcel|color)/i;
const msgsCliente = (Array.isArray(decidir.conversation) ? decidir.conversation : []).filter((m) => m && m.role === 'user').map((m) => String(m.content || ''));
const ultimos3 = msgsCliente.slice(-3);
const msgActual = String(decidir.userMessage || '');
const hitPapelActual = PAPEL_RE.test(msgActual);
const hitPapelHistorial = ultimos3.slice(0, -1).some((t) => PAPEL_RE.test(t));
// hit del turno actual dispara SIEMPRE (negacion ciega aceptada, r3); hit del
// historial se suprime si el cliente se CORRIGE explicito en el turno actual.
const papelEspecialHit = hitPapelActual || (hitPapelHistorial && !CORRECCION_RE.test(msgActual));
// Gramajes ANCLADOS por el cliente (nunca numeros pelados: '120 paginas' no es gramaje).
const extraerGramajes = (txt) => {
  const out = new Set(); let m;
  const re1 = /\b(\d{2,3})\s*(?:gr|grs|gramos)\b/gi;
  const re2 = /obra\s+(?:de\s+)?(\d{2,3})\b/gi;
  while ((m = re1.exec(txt))) out.add(m[1]);
  while ((m = re2.exec(txt))) out.add(m[1]);
  return out;
};
const gramajesCliente = extraerGramajes(ultimos3.join('\n') || msgActual);
// r6 GUARD FAZ INVERSA (caso 14 ronda 2): cliente pidio SIMPLE faz y la fila
// resuelta es doble faz -> numero equivocado con cara de correcto -> repregunta.
const pidioSF = /simple\s*faz|\bs\s*\/\s*f\b|una\s+sola\s+(?:cara|faz)|de\s+un\s+solo\s+lado/i.test(msgActual);
// r6 GUARD NICHO (casos 4/5 ronda 2): producto de precio especial por rubro
// (medicina) solo aplica si el cliente nombro el nicho en la ventana.
const NICHOS = [{ re: /medicin/i, pregunta: '¿Es material de medicina (módulos/apuntes de la facultad)? Tenemos un precio especial para eso. Si no, contame qué querés imprimir y te paso las opciones.' }];
const nichoDe = (nombre) => NICHOS.find((n) => n.re.test(String(nombre || ''))) || null;
const ventanaCliente = msgsCliente.join('\n') || msgActual;

const MAX_RANGOS = 6;
const CAVEAT = ' (precio de lista; el precio final del trabajo te lo confirma el equipo)';
// Anti-eco: si el template del LLM ya dice "precio de lista", el caveat inyectado
// no lo repite (version corta). La parte esencial (el final lo confirma el equipo)
// queda SIEMPRE pegada al numero.
const CAVEAT_CORTO = ' (el precio final del trabajo te lo confirma el equipo)';
const fmt = (n) => '$' + new Intl.NumberFormat('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(n));
// F3: una variante "legible" tiene al menos una letra o digito (la clase "." no se
// muestra). "única" es la etiqueta SINTETICA que el catalogo publica para los
// mono-variante (no es un nombre real) -> tampoco se muestra.
const normNV = (s) => String(s || '').toLowerCase().replace(/[áéíóúñ]/g, (c) => ({ 'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ñ': 'n' }[c])).replace(/\s+/g, ' ').trim();
const nombreVar = (v, canon) => {
  const s = String(v || '').trim();
  if (!/[a-z0-9]/i.test(s)) return '';
  if (/^[uú]nica$/i.test(s)) return '';
  // I5 (ronda suite-5): variante que se llama IGUAL que el producto -> ocultarla
  // (si no, el render duplica: 'La opción X de X').
  if (canon && normNV(s) === normNV(canon)) return '';
  return s;
};

const todo = $input.all().map((i) => i.json).filter((r) => r && r.precio_lista !== undefined);
const porIdx = {};
for (const r of todo) { const k = Number(r.idx) || 1; (porIdx[k] = porIdx[k] || []).push(r); }

function evaluar(rowsIn, variPedida) {
  let rows = rowsIn;
  const filas = rows.length;
  // F2: quedarse con el mejor match_rank (exacto/sinonimo=1 le gana a contains=2)
  if (rows.length > 1) {
    const best = Math.min(...rows.map((r) => Number(r.match_rank) || 9));
    rows = rows.filter((r) => (Number(r.match_rank) || 9) === best);
  }
  let estado, row = null, rangos = null, rangosRaw = null;
  if (rows.length === 1) {
    row = rows[0];
    const nQr = Number(row.n_reglas_cantidad) || 0;
    let raw = row.rangos_cantidad;
    if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = null; } }

    if (row.tiene_override) {
      estado = 'fallback: override';
    } else if (nQr > 1) {
      // >1 regla de cantidad: el motor resuelve precedencia de scope que aca no
      // replicamos -> una tabla elegida al azar seria mentirosa.
      estado = 'fallback: qr_multiple';
    } else if (nQr === 1) {
      const ok = Array.isArray(raw) && raw.length > 0 && raw.length <= MAX_RANGOS
        && raw.every((r) => r && Number(r.value) > 0 && Number(r.minQty) >= 1);
      estado = ok ? 'ok_rangos' : 'fallback: rangos_invalidos';
      if (ok) { rangos = [...raw].sort((a, b) => Number(a.minQty) - Number(b.minQty)); rangosRaw = raw; }
    } else if (!(Number(row.precio_lista) > 0)) {
      // Variantes reales con precio 0 en el catalogo (ej. Papel Vegetal x10): un
      // "$0,00" seria absurdo -> cotiza el equipo.
      estado = 'fallback: precio_cero';
    } else {
      // Sin gate de frescura (decision Martin 2026-07-21: la lista esta conectada al
      // sistema diario del mostrador -> la fuente es viva). El airbag es el tag
      // (precio>90d) en notas: si aparece, esa conexion dejo de ser verdad.
      estado = row.tiene_reglas ? 'ok_caveat' : 'ok';
    }

    // BACKSTOP DOBLE FAZ: pedido d/f sobre variante cuyo nombre NO es d/f -> el
    // numero/tabla (simple faz) sub-cotizaria (DORSO 50% OFF encarece) -> sin numero.
    if (estado === 'ok' || estado === 'ok_caveat' || estado === 'ok_rangos') {
      const pidioDF = /doble\s*faz|\bd\s*\/\s*f\b|frente\s*y\s*dorso|de\s+los\s+dos\s+lados|ambas\s+caras/i.test(decidir.userMessage || '');
      // r6-review H1: SOLO datos de DB — el eco del LLM (variPedida) bypaseaba el
      // guard: con el escape mono, un pedido doble faz sacaba el precio simple-faz.
      const varianteEsDF = /doble|dorso|d\s*\/\s*f/i.test(String(row.variante || '') + ' ' + String(row.nombre_canonico || ''));
      if (pidioDF && !varianteEsDF) estado = 'fallback: dorso';
      // BACKSTOP PAPEL ESPECIAL (v7 ronda 3): los productos por_pagina tienen
      // recargos OPT-IN de papel (bookcel / papel de color / upgrade de gramaje)
      // coexistiendo con sus tablas -> si el cliente pide un papel que la linea
      // no lista, el numero/total estandar sub-cotizaria. Scopeado a por_pagina
      // (cero falsos positivos fuera del catalogo de impresiones). El ancla
      // papel/hojas es deliberada: 'simple faz color' o 'impresion a color'
      // JAMAS matchean; 'no quiero papel de color' si (falso positivo aceptado,
      // direccion segura, mismo trade-off que el dorso).
      if ((estado === 'ok' || estado === 'ok_caveat' || estado === 'ok_rangos') && row.por_pagina
          && /book\s*cell?|(?:papel(?:es)?|hojas?)\s+(?:de\s+)?(?:color(?:es)?|celestes?|amarill\w*|rosad\w*|rosas?|verdes?|azul(?:es)?|roj[ao]s?|naranjas?|violetas?|lilas?|cremas?|fucsias?|gris(?:es)?|negr[ao]s?)|m[aá]s\s+grueso|mejor\s+papel|papel\s+mejor/i && false) { /* regex movida a papelEspecialHit (ventana r4) */ }
      if ((estado === 'ok' || estado === 'ok_caveat' || estado === 'ok_rangos') && row.por_pagina && papelEspecialHit) {
        estado = 'fallback: papel_especial';
      }
      // GUARD NUMERALES (v7 r4 — clase plata I2): el cliente anclo un gramaje
      // (75/106/80...) y la fila resuelta trae OTRO -> numero correcto del producto
      // equivocado (visto DOS veces en suite-5 real). Sin numero, email honesto.
      // Si el gramaje resuelto esta ENTRE los mencionados, no dispara (comparaciones).
      if ((estado === 'ok' || estado === 'ok_caveat' || estado === 'ok_rangos') && gramajesCliente.size) {
        const gramajesFila = extraerGramajes(String(row.nombre_canonico || '') + ' ' + String(row.variante || ''));
        if (gramajesFila.size && !Array.from(gramajesFila).some((g) => gramajesCliente.has(g))) {
          estado = 'fallback: producto_incoherente';
        }
      }
      // r6: faz inversa (espejo del dorso) — pidio simple faz, fila doble faz
      if ((estado === 'ok' || estado === 'ok_caveat' || estado === 'ok_rangos') && pidioSF
          && /doble|dorso|d\s*\/\s*f/i.test(String(row.variante || ''))) {
        estado = 'fallback: faz_incoherente';
      }
      // r6: producto nicho no mencionado -> jamas su precio especial
      if (estado === 'ok' || estado === 'ok_caveat' || estado === 'ok_rangos') {
        const ni = nichoDe(row.nombre_canonico);
        if (ni && !ni.re.test(ventanaCliente)) estado = 'fallback: producto_nicho';
      }
    }
  } else {
    estado = errItem ? 'fallback: sql_error' : rows.length === 0 ? 'fallback: sin_match' : 'fallback: ambiguo';
  }
  return { estado, row, rangos, rangosRaw, filas, rows };
}

// Nombre honesto para el render: el canonico de la DB cuando las filas resueltas son
// de un MISMO producto (cubre el fallback con row y el ambiguo mono-producto de rank 3);
// si no hay filas o son de productos distintos, el eco del LLM.
const nombreProd = (ev, eco) => {
  const rs = (ev && ev.rows) || [];
  return rs.length && rs.every((r) => r.producto_id === rs[0].producto_id) ? rs[0].nombre_canonico : eco;
};

const main = evaluar(porIdx[1] || [], p.variante);
const extras = (p.mas || []).map((m, i) => ({ m, ev: evaluar(porIdx[i + 2] || [], m.variante) }));

let estado = main.estado;
const row = main.row, rangos = main.rangos;
// Cantidad-first (v10.7): con cantidad valida y tabla, numero unico del bracket exacto
// (espejo del motor: PRIMER rango en orden original del array, bordes inclusive).
// Gap entre brackets o cantidad invalida -> tabla completa (nunca el precio base:
// ese gap es zona de negociacion del mostrador).
const qtyPedida = Number.isInteger(p.cantidad) && p.cantidad >= 1 && p.cantidad <= 999999 ? p.cantidad : null;
// v7: paginas/copias (documentos por pagina). Solo actuan si el producto resuelto
// tiene por_pagina=true (backstop: 'mi banner tiene 6 panios' jamas multiplica).
const pagPedidas = Number.isInteger(p.paginas) && p.paginas >= 1 && p.paginas <= 5000 ? p.paginas : null;
const copiasPedidas = Number.isInteger(p.copias) && p.copias >= 1 && p.copias <= 1000 ? p.copias : 1;
const porPagina = !!(row && row.por_pagina);
const CAP_TOTAL = 10000; // cap comercial: por encima, el total lo cotiza el equipo
let modo = null, cantidadEfectiva = null;
if (pagPedidas !== null && porPagina) { modo = 'paginas'; cantidadEfectiva = pagPedidas * copiasPedidas; }
else if (qtyPedida !== null) { modo = 'cantidad'; cantidadEfectiva = qtyPedida; }
// PACK (v7 r4 — clase plata I8): cantidad horneada en el nombre ('500 Tarjetas',
// 'x Millar') -> el precio es POR PACK: la cantidad del cliente JAMAS multiplica
// ni elige bracket ($28.000 x 150 = $4.200.000 visto en suite-5 real). Flag
// curado por_pack (migracion v7b + pasada de curacion); regex SOLO telemetria.
const porPack = !!(row && row.por_pack);
if (porPack) { modo = null; cantidadEfectiva = null; }
// gate doble faz (variante d/f + paginas): unidad pagina-vs-hoja DESCONOCIDA (gate
// TG item 31) -> ni bracket ni total; tabla o unitario + linea fija.
const varianteResueltaDF = /doble|dorso|d\s*\/\s*f/i.test(String((row && row.variante) || ''));
const dfGate = varianteResueltaDF && modo === 'paginas';
const capGate = cantidadEfectiva !== null && cantidadEfectiva > CAP_TOTAL;
const findBr = (q) => (Array.isArray(main.rangosRaw) ? (main.rangosRaw.find((r) => r && q >= Number(r.minQty) && (r.maxQty === null || r.maxQty === undefined || q <= Number(r.maxQty))) || null) : null);
const LINEA_DF = 'El total del doble faz te lo confirma el equipo.';
const LINEA_CAP = 'Para ese volumen, el total te lo cotiza el equipo.';
const LINEA_VOLUMEN = 'Por el volumen total puede quedar mas abajo; el equipo te lo confirma con el archivo.';
// v7: resolucion de bracket + total segun modo. dfGate y capGate degradan a tabla
// (la conducta segura ya calibrada), nunca a un numero que pueda sub-cotizar.
let bracket = null, unitPag = null, totalMonto = null, volumenHint = false, gapPaginas = false;
if (estado === 'ok_rangos' && modo === 'cantidad' && !dfGate && !capGate) {
  bracket = findBr(qtyPedida);
  if (bracket) { estado = 'ok_bracket'; totalMonto = qtyPedida * Number(bracket.value); }
} else if (estado === 'ok_rangos' && modo === 'paginas' && !dfGate && !capGate) {
  // bracket key = paginas (por copia); el max() con el lookup del total cubre
  // rulesets no monotonos: techo bajo AMBAS practicas del mostrador (Fable r2).
  const b1 = findBr(pagPedidas);
  if (!b1) { gapPaginas = true; /* gap en la key -> tabla, sin rescate */ }
  else {
    const b2 = findBr(cantidadEfectiva);
    unitPag = b2 ? Math.max(Number(b1.value), Number(b2.value)) : Number(b1.value);
    volumenHint = copiasPedidas >= 2 && !!b2 && Number(b2.value) < Number(b1.value);
    totalMonto = cantidadEfectiva * unitPag;
    estado = 'ok_paginas';
  }
}
// total sobre precio fijo (sin tabla): ok siempre; ok_caveat SOLO si la lista es
// techo garantizado (solo_descuentos) — con recargos un total grande sub-cotiza.
const totalPermitidoFijo = row && cantidadEfectiva !== null && !dfGate && !capGate
  && (estado === 'ok' || (estado === 'ok_caveat' && row.solo_descuentos === true));
if (totalPermitidoFijo) totalMonto = cantidadEfectiva * Number(row.precio_lista);
const vv = nombreVar(row && row.variante, row && row.nombre_canonico); // SOLO DB: el eco del LLM (p.variante) puede ser el nombre del producto entero -> 'X de X'

let reply;
let accionLog = 'informo_precio';
if (estado === 'ok' || estado === 'ok_caveat') {
  const np = nombreProd(main, p.producto);
  const quien = np ? ((vv ? 'La opción ' + vv + ' de ' : '') + np) : 'Esa opción';
  if (totalPermitidoFijo && totalMonto !== null) {
    // v7: TODO total va en plantilla forzada — cantidad, estimado y condicion en la
    // MISMA frase (disciplina anti-screenshot de ok_bracket, extendida).
    const detalle = modo === 'paginas'
      ? 'por ' + pagPedidas + ' páginas' + (copiasPedidas > 1 ? ' x ' + copiasPedidas + ' copias (' + cantidadEfectiva + ' impresiones)' : '')
      : 'por ' + cantidadEfectiva + ' unidades';
    reply = quien + ' sale ' + fmt(row.precio_lista) + ' c/u — ' + detalle + ', total estimado ' + fmt(totalMonto) + CAVEAT + '.';
    if (volumenHint) reply += '\n' + LINEA_VOLUMEN;
  } else {
    const yaDiceLista = !p.forzarPlantilla && p.template && /precio de lista/i.test(p.template);
    const monto = fmt(row.precio_lista) + (estado === 'ok_caveat' ? (yaDiceLista ? CAVEAT_CORTO : CAVEAT) : '');
    const plantilla = np
      ? ((vv ? 'La opción ' + vv + ' de ' : '') + np + ' sale ' + monto + '.')
      : 'Sale ' + monto + '.';
    reply = p.forzarPlantilla || !p.template ? plantilla : p.template.split('{{PRECIO}}').join(monto);
    if (dfGate) reply += '\n' + LINEA_DF;
    if (capGate) reply += '\n' + LINEA_CAP;
  }
} else if (estado === 'ok_bracket') {
  // Plantilla SIEMPRE forzada y la cantidad DENTRO de la frase: el numero viaja
  // pegado a su condicion (proteccion screenshot). v7: + total estimado.
  const np = nombreProd(main, p.producto);
  reply = 'Por ' + qtyPedida + ' unidades, ' + (vv && np ? 'la opción ' + vv + ' de ' + np : (np || 'esa opción')) + ' sale ' + fmt(bracket.value) + ' c/u — total estimado ' + fmt(totalMonto) + CAVEAT + '.';
} else if (estado === 'ok_paginas') {
  const np = nombreProd(main, p.producto);
  const quien = vv && np ? 'la opción ' + vv + ' de ' + np : (np || 'esa opción');
  const detalle = 'Por ' + pagPedidas + ' páginas' + (copiasPedidas > 1 ? ' x ' + copiasPedidas + ' copias (' + cantidadEfectiva + ' impresiones)' : '');
  reply = detalle + ', ' + quien + ' sale ' + fmt(unitPag) + ' c/u — total estimado ' + fmt(totalMonto) + CAVEAT + '.';
  if (volumenHint) reply += '\n' + LINEA_VOLUMEN;
} else if (estado === 'ok_rangos') {
  // SIEMPRE plantilla forzada: una tabla no entra en un {{PRECIO}} en medio de
  // oracion. Formato guion-por-linea (el mismo que el prompt usa para enumerar).
  const unidadOk = row.unidad && !/^a\d|^\d|\dx\d|cm|mm/i.test(String(row.unidad).trim());
  const np = nombreProd(main, p.producto);
  const quien = (vv && np) ? vv + ' de ' + np : (np || 'Ese producto');
  const encab = quien + ', precio de lista' + (unidadOk ? ' por ' + String(row.unidad).trim().toLowerCase() : '') + ' según cantidad:';
  const lineas = rangos.map((r) => {
    const desde = Number(r.minQty);
    const hasta = r.maxQty === null || r.maxQty === undefined ? null : Number(r.maxQty);
    const rot = hasta === null ? desde + ' o más' : desde === hasta ? String(desde) : desde + ' a ' + hasta;
    return '- ' + rot + ': ' + fmt(r.value) + ' c/u';
  });
  // Sin pie: el encabezado ya dice "precio de lista" (el hedge) y la tabla viaja en bloque con el.
  reply = encab + '\n' + lineas.join('\n');
  // v7: cuando la tabla es la degradacion segura de un total pedido, decir por que.
  if (dfGate) reply += '\n' + LINEA_DF;
  else if (capGate) reply += '\n' + LINEA_CAP;
} else {
  // r6: los fallos de RESOLUCION no derivan a email (decision Martin 2026-07-22:
  // WhatsApp informa todo; el email es para ENCARGAR) -> repregunta que deja la
  // ruta en el especialista (accionLog pregunto_opciones). El email queda para
  // los precios que el sistema legitimamente no puede dar (override, qr_multiple,
  // precio_cero, dorso, papel_especial, producto_incoherente, sql_error).
  const REPREGUNTA = {
    'fallback: sin_match': 'No estoy seguro de qué producto es. ¿Me lo decís de nuevo o me contás para qué lo necesitás? Así te paso las opciones y el precio.',
    'fallback: faz_incoherente': '¿Lo querés simple faz o doble faz? Así te paso el precio justo.',
    'fallback: producto_nicho': (nichoDe((main.row && main.row.nombre_canonico) || (main.rows && main.rows[0] && main.rows[0].nombre_canonico)) || {}).pregunta || 'Contame un poco más qué necesitás y te paso las opciones.',
  };
  let gruposResc = null;
  if (estado === 'fallback: ambiguo' && main.rows && main.rows.length >= 2 && main.rows.length <= 12) {
    // menu rescate deterministico con las filas REALES que resolvieron (mismo
    // formato que Armar Menu Opciones -> el especialista mapea el numero igual)
    const grupos = [];
    for (const r0 of main.rows) {
      let g = grupos.find((x) => x.id === r0.producto_id);
      if (!g) { g = { id: r0.producto_id, nombre: r0.nombre_canonico, vars: [] }; grupos.push(g); }
      g.vars.push(nombreVar(r0.variante, r0.nombre_canonico) || '');
    }
    // r6-review H6a: el rescate tambien respeta el guard de nicho
    gruposResc = grupos.filter((g) => { const ni = nichoDe(g.nombre); return !(ni && !ni.re.test(ventanaCliente)); });
  }
  if (gruposResc && !gruposResc.length) {
    estado = 'fallback: producto_nicho';
    reply = REPREGUNTA[estado];
    accionLog = 'pregunto_opciones';
  } else if (gruposResc && gruposResc.length) {
    const grupos = gruposResc;
    const lineas = []; let n0 = 0;
    for (const g of grupos) {
      // r6-review H6b: grupo mono con var oculta -> una sola linea con el nombre
      const soloNombre = g.vars.length === 1 && !g.vars[0];
      if (grupos.length > 1 && !soloNombre) lineas.push(g.nombre + ':');
      for (const v0 of g.vars) { n0++; lineas.push((grupos.length > 1 && !soloNombre ? '  ' : '') + n0 + '. ' + (v0 || g.nombre)); }
    }
    const encab0 = grupos.length === 1 ? 'Tenemos estas opciones de ' + grupos[0].nombre + ':' : 'Tenemos estas opciones:';
    reply = encab0 + '\n' + lineas.join('\n') + '\nDecime cuál querés (vale mandar solo el número) y te paso el precio.';
    accionLog = 'pregunto_opciones';
  } else if (REPREGUNTA[estado]) {
    reply = REPREGUNTA[estado];
    accionLog = 'pregunto_opciones';
  } else {
    const mail = decidir.avisoDado ? 'a nuestro mail' : 'a terminalgrafica@gmail.com';
    const np = nombreProd(main, p.producto);
    const prod = np ? 'de ' + np + ' ' : '';
    reply = 'El precio ' + prod + 'te lo cotiza el equipo. Escribinos ' + mail + ' con el detalle y te pasan el número.';
  }
  // anti-loop de repregunta (espejo del menu): la misma repregunta 2 veces
  // recientes -> derivacion fija a email (nunca 3 repreguntas identicas)
  if (accionLog === 'pregunto_opciones') {
    const normRep0 = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
    const rec0 = Array.isArray(decidir.lastBotReplies) ? decidir.lastBotReplies : [];
    if (rec0.filter((r0) => normRep0(r0) === normRep0(reply)).length >= 2) {
      const mail = decidir.avisoDado ? 'a nuestro mail' : 'a terminalgrafica@gmail.com';
      reply = 'Escribinos ' + mail + ' con lo que necesitás y el equipo te cotiza directo.';
      accionLog = 'informo_precio';
    }
  }
}

// F4: extras del campo 'mas' — render deterministico por item, independiente del main.
// Tabla completa de un extra NO se renderiza (dos tablas en un WhatsApp es sopa):
// se ofrece, y el follow-up lo resuelve el flujo single ya calibrado.
for (const { m, ev } of (accionLog === 'pregunto_opciones' ? [] : extras)) {
  const vvx = nombreVar(ev.row && ev.row.variante, ev.row && ev.row.nombre_canonico);
  const packX = !!(ev.row && ev.row.por_pack);
  const qx = !packX && Number.isInteger(m.cantidad) && m.cantidad >= 1 && m.cantidad <= CAP_TOTAL ? m.cantidad : null;
  if (ev.estado === 'ok' || ev.estado === 'ok_caveat') {
    const totalOkX = qx !== null && (ev.estado === 'ok' || (ev.row && ev.row.solo_descuentos === true));
    const montoX = fmt(ev.row.precio_lista) + (ev.estado === 'ok_caveat' && !totalOkX ? CAVEAT : '');
    reply += '\n' + (vvx ? 'La opción ' + vvx + ' de ' : '') + nombreProd(ev, m.producto) + ' sale ' + montoX
      + (totalOkX ? ' c/u — por ' + qx + ', total estimado ' + fmt(qx * Number(ev.row.precio_lista)) + CAVEAT : '') + '.';
  } else if (ev.estado === 'ok_rangos') {
    let bx = null;
    if (qx !== null && Array.isArray(ev.rangosRaw)) bx = ev.rangosRaw.find((r) => r && qx >= Number(r.minQty) && (r.maxQty === null || r.maxQty === undefined || qx <= Number(r.maxQty))) || null;
    if (bx) reply += '\nEl de ' + nombreProd(ev, m.producto) + ': por ' + qx + ' unidades sale ' + fmt(bx.value) + ' c/u — total estimado ' + fmt(qx * Number(bx.value)) + CAVEAT + '.';
    else reply += '\nEl de ' + nombreProd(ev, m.producto) + ' va por cantidad; si querés te paso la tabla.';
  } else {
    reply += '\nEl de ' + nombreProd(ev, m.producto) + ' te lo cotiza el equipo por mail.';
  }
}

return [{
  json: {
    reply,
    estado,
    accionLog,
    productoResuelto: row ? row.producto_id : null,
    filasSql: main.filas,
    conversationId: parsear.conversationId,
    accountId: parsear.accountId,
    userMessage: parsear.userMessage,
    notas: (nombreProd(main, null) || p.producto || '?') + ' | ' + (p.variante || '?') + ' | ' + estado
      + (row && Number(row.match_rank) === 2 ? ' (match parcial)' : '')
      + (main.rows && main.rows[0] && Number(main.rows[0].match_rank) === 3 ? ' (resuelto por variante)' : '')
      + (qtyPedida !== null ? ' (cantidad=' + qtyPedida + ')' : '')
      + (pagPedidas !== null ? ' (paginas=' + pagPedidas + 'x' + copiasPedidas + ')' : '')
      + (pagPedidas !== null && !porPagina && row ? ' (paginas ignoradas: no por_pagina)' : '')
      + (pagPedidas !== null && qtyPedida !== null && modo === 'paginas' ? ' (cantidad ignorada: paginas presentes)' : '')
      + (porPagina ? ' (por_pagina)' : '')
      + (totalMonto !== null ? ' (total=' + totalMonto + ')' : '')
      + (dfGate ? ' (df_gate)' : '') + (capGate ? ' (cap_volumen)' : '')
      + (gapPaginas ? ' (gap paginas)' : '') + (volumenHint ? ' (volumen_hint)' : '')
      + (Array.isArray(p.flags) && p.flags.length ? ' [' + p.flags.join(',') + ']' : '')
      + (accionLog === 'pregunto_opciones' ? ' (repregunta)' : '')
      + (main.rows && main.rows.length === 1 && p.variante && main.rows[0].variante && normNV(main.rows[0].variante) !== normNV(p.variante) ? ' (variante rescatada: mono)' : '')
      + (porPack && (qtyPedida !== null || pagPedidas !== null) ? ' (cantidad ignorada: pack)' : '')
      + (!porPack && cantidadEfectiva !== null && row && /(^|[^0-9])x\s*[0-9]+|millar|\b[0-9]{2,4}\s+(?:tarjetas?|volantes?|folletos?|unidades|hojas)\b/i.test(String(row.nombre_canonico || '') + ' ' + String(row.variante || '')) ? ' (pack?)' : '')
      + (estado === 'fallback: papel_especial' && !hitPapelActual && hitPapelHistorial ? ' (papel_historial)' : '')
      + (row && (() => { const ts = Date.parse(row.precio_actualizado); return Number.isFinite(ts) && Date.now() - ts > 90 * 86400000; })() ? ' (precio>90d)' : '')
      + ((estado === 'ok' || estado === 'ok_caveat') && p.forzarPlantilla ? ' (plantilla forzada)' : '')
      + (errItem ? ' [' + String(errItem.json.error.message || errItem.json.error).slice(0, 120) + ']' : '')
      + (extras.length ? ' || mas: ' + extras.map((e) => e.m.producto + '=' + e.ev.estado).join(', ') : ''),
  },
  pairedItem: { item: 0 },
}];

// Render deterministico del menu de opciones (action 'opciones'): el LLM nunca
// tipea menus -> no puede filtrar marcas internas ni inventar etiquetas (I3/I4).
// Numerado (r5: el eco de un numero es mas robusto que el de un string).
const parsear = $('Parsear Respuesta').first().json;
const decidir = $('Decidir').first().json;
const op = parsear.opciones || {};
const faltan = Array.isArray(op.faltan) ? op.faltan : [];
const rows = $input.all().map((i) => i.json).filter((r) => r && r.producto_id);

const productos = [];
for (const r of rows) {
  let p = productos.find((x) => x.id === r.producto_id);
  if (!p) { p = { id: r.producto_id, nombre: r.nombre_canonico, porPagina: !!r.por_pagina, vars: [] }; productos.push(p); }
  const v = String(r.variante || '').trim();
  const legible = /[a-z0-9]/i.test(v) && !/^[uú]nica$/i.test(v);
  p.vars.push({ nombre: legible ? v : '', qr: Number(r.n_reglas_cantidad) || 0 });
}

// r6 GUARD NICHO: producto de precio especial por rubro (medicina) solo entra
// al menu si el cliente nombro el nicho en sus ultimos mensajes.
const NICHOS = [{ re: /medicin/i, pregunta: '¿Es material de medicina (módulos/apuntes de la facultad)? Tenemos un precio especial para eso. Si no, contame qué querés imprimir y te paso las opciones.' }];
const msgsCli = (Array.isArray(decidir.conversation) ? decidir.conversation : []).filter((m) => m && m.role === 'user').map((m) => String(m.content || '')).join('\n') || String(decidir.userMessage || '');
let nichoFiltrado = null;
for (let i = productos.length - 1; i >= 0; i--) {
  const ni = NICHOS.find((x) => x.re.test(String(productos[i].nombre || '')));
  if (ni && !ni.re.test(msgsCli)) { nichoFiltrado = ni; productos.splice(i, 1); }
}
// r6 (nota Martin ronda 2, caso 21): orden natural — los numeros ordenan como
// numeros ('100 Tarjetas' < '500' < '1000', no orden de string)
const natKey = (s) => String(s || '').toLowerCase().replace(/\d+/g, (d) => d.padStart(8, '0'));
productos.sort((a, b) => natKey(a.nombre) < natKey(b.nombre) ? -1 : natKey(a.nombre) > natKey(b.nombre) ? 1 : 0);

let reply, notas;
const soloDatos = faltan.length > 0 && faltan.every((f) => ['cantidad', 'paginas', 'copias'].includes(f));

if (!productos.length) {
  if (nichoFiltrado) {
    // r6: el unico candidato era el producto nicho no mencionado -> repregunta honesta
    reply = nichoFiltrado.pregunta;
    notas = 'menu_nicho | ' + (op.productos || []).join(' / ');
  } else {
    // el LLM mando nombres irresolubles -> reply fijo (sin 2a llamada) + telemetria
    // de curacion (gaps de sinonimos entran por aca).
    reply = '¿Me decís qué producto querés cotizar? Así te paso las opciones que tenemos.';
    notas = 'menu_sin_match | ' + (op.productos || []).join(' / ');
  }
} else if (soloDatos && productos.length === 1) {
  // producto+opcion definidos: preguntar SOLO lo que falta, ecoando lo elegido —
  // NUNCA el menu completo (re-preguntar lo dado es regla sagrada).
  const q = [];
  if (faltan.includes('paginas')) q.push('cuántas páginas tiene tu documento');
  if (faltan.includes('copias')) q.push('cuántas copias querés');
  if (faltan.includes('cantidad')) q.push('cuántas necesitás');
  reply = 'Para ' + productos[0].nombre + ', decime ' + q.join(' y ') + ' y te paso el precio.';
  notas = 'faltan: ' + faltan.join(',') + ' | ' + productos[0].nombre;
} else if (productos.length === 1 && productos[0].vars.length === 1) {
  // r6 (nota Martin ronda 2, caso 5): UNA sola opcion no es un menu — frase natural
  const p1 = productos[0];
  const et = p1.vars[0].nombre && p1.vars[0].nombre.toLowerCase() !== p1.nombre.toLowerCase() ? p1.nombre + ' (' + p1.vars[0].nombre + ')' : p1.nombre;
  let preg;
  if (p1.porPagina) preg = 'decime cuántas páginas tiene tu documento y cuántas copias querés y te paso el precio.';
  else if (p1.vars[0].qr === 1) preg = 'decime cuántas necesitás y te paso el precio.';
  else preg = '¿te paso el precio de lista?';
  reply = 'Para eso tenemos ' + et + ': ' + preg;
  notas = 'menu_unico: ' + p1.nombre + (faltan.length ? ' | faltan: ' + faltan.join(',') : '');
} else {
  // r6 pivot de packs (nota Martin ronda 2, caso 21): misma familia con variantes
  // identicas ('100/500/1000 Tarjetas...') -> variantes UNA vez + packs en el header.
  const fam = productos.map((p) => { const m = String(p.nombre).match(/^(\d+)\s+(.+)$/); return m ? { pack: Number(m[1]), resto: m[2] } : null; });
  const varsKey = (p) => p.vars.map((v) => (v.nombre || '').toLowerCase()).join('|');
  const esFamilia = productos.length > 1 && fam.every(Boolean) && fam.every((f) => f.resto === fam[0].resto) && productos.every((p) => varsKey(p) === varsKey(productos[0]));
  const lineas = [];
  let n = 0;
  if (esFamilia) {
    const packs = fam.map((f) => f.pack).sort((a, b) => a - b);
    lineas.push(fam[0].resto + ' — packs de ' + (packs.length > 1 ? packs.slice(0, -1).join(', ') + ' o ' + packs[packs.length - 1] : String(packs[0])) + ':');
    for (const v of productos[0].vars) { n++; lineas.push(n + '. ' + (v.nombre || fam[0].resto)); }
    reply = 'Tenemos estas opciones:\n' + lineas.join('\n') + '\nDecime cuál opción querés (vale mandar solo el número) y de qué pack.';
    notas = 'menu_pack: ' + fam[0].resto + ' [' + packs.join('/') + '] (' + n + ' opciones)' + (faltan.length ? ' | faltan: ' + faltan.join(',') : '');
  } else {
    for (const p of productos) {
      if (productos.length > 1) lineas.push(p.nombre + ':');
      for (const v of p.vars) { n++; lineas.push((productos.length > 1 ? '  ' : '') + n + '. ' + (v.nombre || p.nombre)); }
    }
    const preguntas = ['decime cuál opción querés (vale mandar solo el número)'];
    if (productos.some((p) => p.porPagina)) preguntas.push('cuántas páginas tiene tu documento y cuántas copias querés');
    else if (productos.some((p) => p.vars.some((v) => v.qr === 1))) preguntas.push('cuántas necesitás');
    reply = 'Tenemos estas opciones:\n' + lineas.join('\n') + '\nPara cotizarte, ' + preguntas.join(' y ') + '.';
    notas = 'menu: ' + productos.map((p) => p.nombre).join(' / ') + ' (' + n + ' opciones)' + (faltan.length ? ' | faltan: ' + faltan.join(',') : '');
  }
}

// ANTI-LOOP (r5): el mismo menu 2 veces recientes -> derivacion fija en vez del
// tercero (esta rama bypasea el anti-repeticion de Parsear).
const normRep = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const recientes = Array.isArray(decidir.lastBotReplies) ? decidir.lastBotReplies : [];
let antiLoop = false;
if (recientes.filter((r) => normRep(r) === normRep(reply)).length >= 2) {
  antiLoop = true;
  reply = 'Escribinos ' + (decidir.avisoDado ? 'a nuestro mail' : 'a terminalgrafica@gmail.com') + ' con lo que necesitás y el equipo te cotiza directo.';
  notas = (notas || '') + ' | anti-loop menu';
}

return [{ json: { reply, notas, antiLoop, conversationId: parsear.conversationId, accountId: parsear.accountId, userMessage: parsear.userMessage }, pairedItem: { item: 0 } }];

// Isla de mantenimiento (sin conexión al flujo principal): purga el cache del
// catálogo en staticData. Solo persiste en ejecuciones de PRODUCCIÓN (URL de
// producción con el workflow activo) — el botón Execute del editor no lo guarda.
const sd = $getWorkflowStaticData('global');
const habia = !!sd.catalogo;
const edadSeg = sd.catalogoTs ? Math.round((Date.now() - sd.catalogoTs) / 1000) : null;
delete sd.catalogo;
delete sd.catalogoTs;
return [{ json: { ok: true, cache_purgado: habia, edad_cache_seg: edadSeg } }];
